/// Per-net routing and design constraints.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct NetConstraints {
    /// Maximum total trace length (mm).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_trace_length: Option<f64>,
    /// Minimum trace width (mm).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_trace_width: Option<f64>,
    /// Target single-ended impedance (ohms).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target_impedance: Option<f64>,
    /// Length matching group name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub length_match_group: Option<String>,
    /// Length matching tolerance (mm).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub length_match_tolerance: Option<f64>,
    /// Differential pair partner net.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub diff_pair_partner: Option<NetId>,
    /// Target differential impedance (ohms).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target_diff_impedance: Option<f64>,
    /// Route priority (higher = routes first).
    #[serde(default)]
    pub route_priority: i32,
    /// Disallowed layers.
    #[serde(default)]
    pub exclude_layers: Vec<LayerId>,
}

/// A wire segment on a schematic sheet. Always exactly two endpoints —
/// multi-point polylines must be split into one `Wire` per segment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Wire {
    /// Globally unique identifier for CRDT collaboration.
    #[serde(default = "default_uuid")]
    pub uuid: String,
    /// Which net this wire belongs to (assigned during connectivity analysis).
    pub net: Option<NetId>,
    /// Segment endpoints `[start, end]`.
    pub points: [Vec2; 2],
    /// Which sheet this wire is on.
    pub sheet: SheetId,
}

/// A label on a schematic naming or connecting nets.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Label {
    /// Globally unique identifier for CRDT collaboration.
    #[serde(default = "default_uuid")]
    pub uuid: String,
    /// Which net this label is associated with.
    pub net: Option<NetId>,
    /// Label text (the net name).
    pub text: String,
    /// Position on the schematic sheet.
    pub position: Vec2,
    /// Type of label (local, global, hierarchical).

}

/// A schematic sheet in the hierarchy.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Sheet {
    /// Globally unique identifier for CRDT collaboration.
    #[serde(default = "default_uuid")]
    pub uuid: String,
    /// Display name of the sheet.
    pub name: String,
    /// Filename of the sheet (e.g. "power.kicad_sch").
    pub filename: String,
    /// Parent sheet (None for root).
    pub parent: Option<SheetId>,
    /// Position of the sheet instance on the parent sheet (for rendering).
    #[serde(default)]
    pub instance_position: Vec2,
    /// Size of the sheet instance block on the parent sheet.
    #[serde(default = "default_sheet_size")]
    pub instance_size: Vec2,
    /// Hierarchical pins on the sheet instance border.
    #[serde(default)]
    pub pins: Vec<SheetPin>,
    /// Paper size for this sheet's own drawing area (e.g. A4 = 297x210).
    /// Distinct from `instance_size` which is the block size on the parent.
    #[serde(default = "default_paper_size")]
    pub paper_size: Vec2,
}

fn default_paper_size() -> Vec2 {
    Vec2::new(297.0, 210.0) // A4
}

/// Which edge of a sheet block a hierarchical pin sits on.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SheetPinSide {
    #[default]
    Right,
    Left,
    Top,
    Bottom,
}

/// A hierarchical pin on a sheet instance.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SheetPin {
    /// Pin name (matches hierarchical label in child sheet).
    pub name: String,
    /// Position on the parent sheet (absolute coordinates).
    pub position: Vec2,
    /// Which edge of the sheet block this pin sits on.
    #[serde(default)]
    pub side: SheetPinSide,
}

/// Default size for a sheet instance block on the parent schematic (20mm x 15mm).
pub fn default_sheet_size() -> Vec2 {
    Vec2::new(20.0, 15.0)
}

/// An organizational group spanning schematic or board entities.
///
/// Groups are used for hierarchical selection, autorouter region constraints,
/// multi-entity operations, and schematic readability. Components can belong
/// to at most one group per scope.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Group {
    /// Globally unique identifier for CRDT collaboration.
    #[serde(default = "default_uuid")]
    pub uuid: String,
    /// Display name (e.g., "Power Supply", "USB Interface").
    pub name: String,
    /// Members of this group.
    pub members: Vec<crate::operations::EntityId>,
    /// Scope: which sheet (schematic) or board this group lives in.
    pub scope: GroupScope,
    /// Parent group for nesting (`None` = top-level).
    #[serde(default)]
    pub parent: Option<GroupId>,
    /// Arbitrary metadata (e.g., autorouter directives, placement constraints).
    #[serde(default)]
    pub properties: std::collections::HashMap<String, String>,
}

/// Whether a group lives on the schematic or the board.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum GroupScope {
    /// Group on a specific schematic sheet.
    Schematic(SheetId),
    /// Group on a named board.
    Board(String),
}

#[cfg(test)]
mod legacy_compat_tests {
    use super::*;

    #[test]
    fn board_deserializes_legacy_layer_stack_field() {
        // Pre-c4e12aa boards carried `layer_stack` on-disk. This locks in
        // serde's ignore-unknown-fields behavior against future `deny_unknown_fields`.
        let legacy = r#"{
            "name": "main_board",
            "layer_stack": { "layers": [], "board_thickness": 1.6 }
        }"#;
        let board: Board = serde_json::from_str(legacy).expect("legacy Board JSON must still load");
        assert_eq!(board.name, "main_board");
    }
}
